import{z as l,x as i,o as t,c as C,q as s,j as B,D as e,d as a,s as o,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"吊销与 OCSP","description":"","frontmatter":{"title":"吊销与 OCSP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cert-revoke.md","filePath":"cs/cert-revoke.md","lastUpdated":1791413859000}'),d={name:"cs/cert-revoke.md"};function p(c,E,F,S,D,h){const r=i("Mermaid");return t(),C("div",null,[E[2]||(E[2]=s('<h1 id="吊销与-ocsp" tabindex="-1">吊销与 OCSP <a class="header-anchor" href="#吊销与-ocsp" aria-label="Permalink to &quot;吊销与 OCSP&quot;">​</a></h1><div class="epigraph"><p>证书在有效期内私钥仍可能泄露；吊销列表与在线状态协议把「现在还信不信这张证」从签发时拆出来。</p><footer>—— 据 RFC 5280 对 CRL；OCSP；Anderson 对 PKI 失败模式的整理</footer></div><p><a href="/cs/cert-pki">上一课</a>给出根锚、链与「信任是对签发者」。本课不重做 X.509 字段。缺口是时间：未到期不等于仍安全。CRL 批量发布已吊销序号；OCSP 问一张证的状态。口令课是人的秘密，下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PKI 课留下链。私钥丢失、名称绑错、CA 被逼签发，都要求在 notAfter 之前作废。浏览器若跳过吊销检查，中间人仍可持一张「看起来未过期」的证。缺口是<strong>状态查询合同</strong>：离线 CRL 与在线 OCSP，以及软失败（查不到就放行）如何把规格掏空。<span class="marginnote">两个名词翻译：CRL 是「挂失公告」——CA 定期贴出一张「这些序号已作废」的清单，离线可用但更新慢、名单越滚越长；OCSP 是「打电话问一句」——现场问这张证还有效吗，答案新鲜，但你访问了谁也顺口告诉了 CA。</span></p><p><span class="marginnote">OCSP stapling 把应答钉在服务器握手里，减轻隐私与可达性问题。CRL 体积是运营代价。本课不写攻击者如何骗过软失败。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>签发者维护吊销信息。客户端：链验证通过后查状态，失败则拒绝。缓存要短，以免吊销延迟。短寿命证书把吊销换成「很快过期」，是另一政策。本课只钉检查点，不选厂商策略。</p>',8)),(t(),B(n,null,{default:e(()=>[o(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHAIN%5B%22%E9%93%BE%E9%AA%8C%E8%AF%81%E9%80%9A%E8%BF%87%22%5D%20--%3E%20STAT%5B%22%E6%9F%A5%20CRL%20%E6%88%96%20OCSP%22%5D%0A%20%20STAT%20--%3E%20OK%5B%22%E4%BB%8D%E6%9C%89%E6%95%88%E5%88%99%E7%94%A8%E5%85%AC%E9%92%A5%22%5D%0A%20%20STAT%20--%3E%20REV%5B%22%E5%B7%B2%E5%90%8A%E9%94%80%E5%88%99%E6%8B%92%E7%BB%9D%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("吊销把 PKI 从静态文件变成带时间的系统。它服务真实性：名字与密钥的绑定可被撤回。与 "),A("a",{href:"/cs/tls-handshake"},"TLS 握手"),a(" 的关系：握手必须消费新鲜状态，否则证书课白讲。后课口令是另一身份源，不替代服务器证书。")],-1)),(t(),B(n,null,{default:e(()=>[o(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E9%93%BE%E9%AA%8C%E8%AF%81%E9%80%9A%E8%BF%87%EF%BC%8C%E6%8E%A5%E7%9D%80%E6%9F%A5%E5%90%8A%E9%94%80%E7%8A%B6%E6%80%81%22%5D%20--%3E%20R%7B%22%E6%9F%A5%E8%AF%A2%E8%83%BD%E5%BE%97%E5%88%B0%E7%BB%93%E6%9E%9C%E5%90%97%EF%BC%9F%22%7D%0A%20%20R%20--%3E%7C%22%E6%9F%A5%E5%88%B0%EF%BC%9A%E4%BB%8D%E6%9C%89%E6%95%88%22%7C%20OK%5B%22%E4%BD%BF%E7%94%A8%E5%85%AC%E9%92%A5%22%5D%0A%20%20R%20--%3E%7C%22%E6%9F%A5%E5%88%B0%EF%BC%9A%E5%B7%B2%E5%90%8A%E9%94%80%22%7C%20REJ%5B%22%E6%8B%92%E7%BB%9D%22%5D%0A%20%20R%20--%3E%7C%22%E6%9F%A5%E4%B8%8D%E5%88%B0%E6%88%96%E8%B6%85%E6%97%B6%22%7C%20SOFT%7B%22%E5%A4%B1%E8%B4%A5%E7%AD%96%E7%95%A5%E9%80%89%E5%93%AA%E7%A7%8D%EF%BC%9F%22%7D%0A%20%20SOFT%20--%3E%7C%22%E8%BD%AF%E5%A4%B1%E8%B4%A5%22%7C%20PASS%5B%22%E6%94%BE%E8%A1%8C%EF%BC%9A%E5%90%8A%E9%94%80%E5%B1%82%E8%A2%AB%E6%8E%8F%E7%A9%BA%22%5D%0A%20%20SOFT%20--%3E%7C%22%E7%A1%AC%E5%A4%B1%E8%B4%A5%22%7C%20BLOCK%5B%22%E6%8B%92%E7%BB%9D%EF%BC%9A%E5%8F%AF%E7%94%A8%E6%80%A7%E5%8F%97%E6%8D%9F%22%5D%0A%20%20ATT%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E9%98%BB%E6%96%AD%E6%9F%A5%E8%AF%A2%E7%AB%AF%E5%8F%A3%22%5D%20-.-%3E%7C%22%E5%88%B6%E9%80%A0%E6%9F%A5%E4%B8%8D%E5%88%B0%22%7C%20SOFT%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=s('<p><span class="marginnote">这张图回答「软失败为什么等于没有吊销」：攻击者不需要伪造任何应答，只要让你查不到——网络层阻断 OCSP 端口即可，浏览器按软失败照常放行。软失败的存在理由是可用性（OCSP 服务一宕，全网拒连代价太大），代价是把这一层的否决权交给了能掐断网络的人。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把证书透明日志的全部八卦当主干。人如何证明自己，下一课口令与加盐。</p><p>后课默认：有效期不够，还要状态。人的秘密用盐存哈希。</p><p><span class="marginnote">短寿命证书是另一条出路，直觉像「酸奶只印很短的保质期」：与其贴回收公告（吊销），干脆把有效期缩到几天，泄露的证很快自然失效——Let&#39;s Encrypt 的 90 天证书就是这条思路的温和版。吊销问题被化简成「等它过期」，代价是自动续期必须真的自动化。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>吊销把证书从「未过期」里再砍一刀。</li><li>CRL 批量，OCSP 按张；软失败会取消这层。</li><li>口令存储下一课。</li><li>出处：RFC 5280；Anderson；Stallings。</li></ul>',7))])}const T=l(d,[["render",p]]);export{P as __pageData,T as default};
